namespace std {
    template<typename T>
    class complex;

    // User-defined literal for complex<long double>
    constexpr complex<long double> operator""il(long double d);
    constexpr complex<long double> operator""il(unsigned long long d);
    // Similar literals can be defined for 'i' and 'if' suffixes
}

code_example:
#include <complex>
using namespace std;

constexpr complex<long double> operator""il(long double d) {
    return complex<long double>{0.0L, d};
}

int main() {
    auto c1 = 3.0il; // Creates complex<long double> with real=0.0L, imag=3.0L
    auto c2 = 5il;   // Creates complex<long double> with real=0.0L, imag=5.0L
    // Output the imaginary parts
    cout << "c1: " << c1 << "\n";
    cout << "c2: " << c2 << "\n";
    return 0;
}
